// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 warpSeed) public {
        vm.assume(amount == 10 ether);
        address caller = address(0x1234);
        vm.deal(caller, amount * 5);
        uint256 baseTime = 1000 + (warpSeed % 1000000);
        vm.warp(baseTime);
        vm.roll(1);

        vm.prank(caller);
        (bool success1, ) = address(c).call{value: amount}("");
        vm.assume(success1);
        uint256 oldPast = c.pastBlockTime();

        vm.warp(baseTime);
        vm.roll(2);

        vm.prank(caller);
        (bool success2, ) = address(c).call{value: amount}("");

        if (success2) {
            assertTrue(c.pastBlockTime() > oldPast);
        } else {
            assertTrue(c.pastBlockTime() == oldPast);
        }
    }
}
